INSERT INTO `crs_tabledata717` VALUES ('115', '{F7A0A964-5C44-48EA-AF5C-F6448CC755C0}', '60', 'INHE-0549', '2016-07-18 13:44:46', '0000-00-00 00:00:00', '2016-07-19 13:25:48', 'unchecked', 'n', 'n', '', '2', 'sctz2016071801/NF2-01/生产通知单', '', '2', 'BS安装三相可更换通信模块代码预付费电能表（不含模块）', '待定', '待定', null, null, '待定', '', '', '02', '', '是否第三方检验待定。1mn内耐交流电压:4Kv-50Hz\r\r\r\r\r\r\n耐冲击电压：8KV\r\r\r\r\r\r\n接线方式：对称或非对称,但采取非对称接线时，电表正面（端子盖）应当有清晰，远距可视且不可磨灭的标识。可采用彩色代码。生产商或投标人在提交标书时应当提供关于此点的解释文件。\r\r\r\r\r\r\nRS485通信接口：预留\r\r\r\r\r\r\n保护等级：接线柱外IP54\r\r\r\r\r\r\n是否使用夏令时待定   要求每个电表都必须独立包装在一个密封的塑料包裹里，接着独立包装在加固的纸板盒中。\r每四（4）个电表放置在一个加固的大集体纸板盒中。每个包装上都要标注指定区域部门的名字及其地址。\r\r', '{F7A0A9645C4448EAAF5CF6448CC755C0C0C041FDE37D48DDBD71A1405A7C684E}_NF2技术规格要求.docx');
INSERT INTO `crs_tabledata717` VALUES ('116', '{F8D680E2-92A0-4738-835A-2E5F4D6D51FE}', '60', 'INHE-0549', '2016-07-18 13:44:46', '0000-00-00 00:00:00', '2016-07-19 13:25:48', 'unchecked', 'n', 'n', '', '1', 'sctz2016071801/NF2-01/生产通知单', '', '1', 'BS安装单相可更换通信模块代码预付费电能表（不含模块）', '待定', '待定', null, null, '待定', '', '', '02', '', '是否第三方检验及外箱和内箱设计文件待定。 1mn内交流电压耐力:4Kv-50Hz\r\r\r\r\r\r\r\r\r\r\r\r\r\n耐冲击电压：8KV\r\r\r\r\r\r\r\r\r\r\r\r\r\nRS485通信接口：预留\r\r\r\r\r\r\r\r\r\r\r\r\r\n保护等级：接线柱外IP54\r       是否使用夏令时待定\r\r         要求每个电表都必须独立包装在一个密封的塑料包裹里，接着独立包装在加固的纸板盒中。\r每十二（12）个电表放置在一个加固的大集体纸板盒中。每个包装上都要标注指定区域部门的名字及其地址。\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\n', '{F8D680E292A04738835A2E5F4D6D51FEC0C041FDE37D48DDBD71A1405A7C684E}_NF2技术规格要求.docx');
