INSERT INTO `crs_tabledata717` VALUES ('276', '{2605C6EE-B45A-409A-9254-475F6B5F23A5}', '61', 'INHE-0500', '2017-07-05 13:38:54', '0000-00-00 00:00:00', '2017-07-26 15:08:17', 'unchecked', 'n', 'n', '', '2', 'sctz2017070501/BAP02/生产通知单', '', '2', '三相四线直接接入式GPRS通讯可更换通讯模块智能电表', '无需', '无需', '1', '1', '银河标准', '01', '02', '02', '', '电表供电来源为电力公司和发电机，电表支持电力公司和发电机两种费率，支持外部信号输入由电力公司费率自动切换至发电机费率。此功能之前客户服评审建议：PLC电表通过集中器发指令到电表切换，即由外部单独的通讯线路给指令到集中器，集中器再发给电表切换，GPRS电表直接通过外部单独的通讯线路给指令到电表切换；', '');
