INSERT INTO `crs_tabledata717` VALUES ('360', '{EB4F9377-C71B-45D5-B905-9F11EFC67067}', '61', 'INHE-0675', '2017-10-27 14:35:32', '0000-00-00 00:00:00', '2017-10-27 16:34:35', 'unchecked', 'n', 'n', '', '1', 'sctz2017102702/BFN07/生产通知单', '', '1', '三相四线CT/PT接入可更换模块代码智能电表（GPRS模块）', '研发提供', '研发提供', '0', '0', '无特殊要求', '03', '02', '02', '', '1： 需要测试电池功耗，制作简易工装，所有表计的电池功耗低于10微安（时钟电池），\r\r\r\r\r\r\r\r\n    停电抄表电池功耗在50-80uA.\r\r\r\r\r\r\r\r\n2.出厂默认设置为后付费模式。\r\r\n\r\r\n\r\r\n\r\r\n\r\r\nBFN07的300台CT表和BFN04出货的10台表技术规格一致，只是出厂设置有调整，调整如下：关闭除了有电无电开盖跳闸外，其他所有的跳闸功能。同时电表出厂不再分别标示 低压中亚，统一设置成一种，他们之后根据实际使用的场景，用smarttools设置即可。', '');
