INSERT INTO `crs_tabledata717` VALUES ('502', '{75EAD22F-632C-4A27-AD80-E290BCE8EF6C}', '61', 'INHE-0636', '2018-07-20 15:12:35', '0000-00-00 00:00:00', '2018-07-23 10:29:22', 'unchecked', 'n', 'n', '', '1', 'sctz2018072003/KF03/生产通知单', '', '1', 'Completed Set of Single Phase Pre-Payment Meter (PLC Link)\r\n整机-单相预付费电表（PLC通讯）', '需要，英文', '\r\r\r\r\r\r\n\r\r\r\n需要，英文', null, null, '', '01', '01', '02', '{75EAD22F632C4A27AD80E290BCE8EF6C25C65FD70593441EAB802EB6AC38C11C}_倪明杰核-2018年7月20日   KF03_单相两线(下端接线下进上出）安装PLC双载波通信预付费分体式代码表.xls', '\r\r\r\n\r\r1.1 双回路双继电器，一体式继电器  或者  两个独立继电器 都能接\r\r\r\r\r\n受；\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\n1.2 DIN4，底部进线底部出线，进线靠近底端\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\n2.MCU和CIU都需\r\r\r\r\n要满足IP54；\r\r\r\r\r\r\r\r\r\r\r\n3.启动电流：0.2%Ib#FE54`\r\r\r\r\r\r\r\r\r\r\r\n4.通讯\r\r\r\r\r\r\r\r\r\r\r\n表和集中器：G3 PLC，大于1000米； \r\r\r\r\r\r\r\r\r\r\r\n表和CIU：普通PLC， 大于100米', '{75EAD22F632C4A27AD80E290BCE8EF6CC0C041FDE37D48DDBD71A1405A7C684E}_1.2 KF03技术规格-中英20180720.doc');
