INSERT INTO `crs_tabledata717` VALUES ('766', '{0070948B-EF62-4D2C-BD04-1A4432FCBD28}', '61', 'INHE-0500', '2019-12-04 12:32:06', '0000-00-00 00:00:00', '2019-12-06 17:20:06', 'unchecked', 'n', 'n', '', '1', 'sctz2019120402/EXJ05/生产通知单', '', '1', 'BS单相二线一体式预付费代码表', '电表说明书需要有客户logo，具体烦请工厂工程部和业务确认', 'EXJ02已提供，EXJ05无需提供', '1', '1', '公司标准', '01', '01', '02', '', '1 当前TTA的端子盖太短\r\n经过和Recharger等经销商实地安装测试，我们的端子盖太短（客户要求长度至少70mm），无法覆盖底部的接线容易导致用户轻易接触到底部接线进行窃电（客户安装在室内墙体上，没有表箱）。\r\n此项请公司结合在年均7万台基础上考虑新开端子盖的模具 4万 RMB。\r\n\r\n\r\n2.电表激活后，需要输入固定短代码才能激活开端盖断电功能，此功能和章工沟通后不影响硬件，简单更新程序即可；', '');
